package com.novacommerce.order.api; import com.novacommerce.order.domain.cart.*; import com.novacommerce.order.domain.order.*; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
public final class OrderDtos{private OrderDtos(){}public record ItemRequest(@NotNull UUID variantId,@Min(1)@Max(999)long quantity){}public record QuantityRequest(@Min(1)@Max(999)long quantity){}public record CheckoutRequest(@NotNull UUID cartId){}public record CartResponse(UUID id,String status,long version,List<CartLine>items){static CartResponse from(Cart c){return new CartResponse(c.getId(),c.getStatus().name(),c.getVersion(),c.getItems().stream().sorted(Comparator.comparing(CartItem::getVariantId)).map(i->new CartLine(i.getVariantId(),i.getQuantity())).toList());}}public record CartLine(UUID variantId,long quantity){}public record OrderPage(List<OrderResponse>items,int page,int size,long totalElements,int totalPages){}public record OrderResponse(UUID id,String status,String currency,BigDecimal merchandiseTotal,UUID reservationId,Instant reservationExpiresAt,String cancellationReason,Instant createdAt,List<OrderLine>items){static OrderResponse from(CustomerOrder o){return new OrderResponse(o.getId(),o.getStatus().name(),o.getCurrency(),o.getMerchandiseTotal(),o.getReservationId(),o.getReservationExpiresAt(),o.getCancellationReason(),o.getCreatedAt(),o.getItems().stream().map(i->new OrderLine(i.getVariantId(),i.getProductName(),i.getProductSlug(),i.getVariantName(),i.getSku(),i.getQuantity(),i.getUnitPrice(),i.getLineTotal(),i.getCurrency())).toList());}}public record OrderLine(UUID variantId,String productName,String productSlug,String variantName,String sku,long quantity,BigDecimal unitPrice,BigDecimal lineTotal,String currency){}}
